<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import OnboardingOption from '../../components/onboarding/OnboardingOption.vue'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'
const router = useRouter(); const store = useCompanyOnboardingStore(); const error = ref(''); const businessTypes = [{ label: 'Clínica', value: 'clinic' }, { label: 'Consultório', value: 'office' }, { label: 'Escritório', value: 'business' }, { label: 'Loja', value: 'store' }, { label: 'Prestador de serviços', value: 'services' }, { label: 'Outro', value: 'other' }]
function next() { if (!store.state.profile.businessType || (store.state.profile.businessType === 'other' && !store.state.profile.customBusinessType.trim())) { error.value = 'Escolha uma opção para continuar.'; return }; store.nextStep(); router.push('/cadastro/identificacao') }
</script>
<template><section><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Vamos conhecer sua empresa</h1><p class="mt-5 leading-7 text-neutral-600">Essas informações serão usadas para configurar seu espaço de trabalho.</p><h2 class="mt-10 text-lg font-medium">Qual é o tipo da sua empresa?</h2><div class="mt-5 grid gap-3 sm:grid-cols-2"><OnboardingOption v-for="option in businessTypes" :key="option.value" :label="option.label" :value="option.value" :selected="store.state.profile.businessType === option.value" @select="store.updateProfile({ businessType: $event })" /></div><input v-if="store.state.profile.businessType === 'other'" v-model="store.state.profile.customBusinessType" placeholder="Qual é o tipo da sua empresa?" class="mt-4 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" /><p v-if="error" class="mt-3 text-sm text-red-600">{{ error }}</p><BaseButton class="mt-8 min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" @click="next">Continuar</BaseButton></section></template>
